#!/usr/bin/env node
// Renders the public fictional March 2026 statement and ledger as SCANNED documents for the OCR path: a two-page
// image-only PDF bank statement and a one-page PNG ledger, slightly tilted and toned like a scan. Rendered with a
// local headless Chrome (CHROME env var), so the bytes depend on the browser build; they are pinned in the
// manifest written by scripts/generate-unfamiliar-documents.mjs rather than regenerated by --check.
// Usage: CHROME=/path/to/chrome node scripts/generate-scanned-documents.mjs   (SCAN_PAGES_DIR=dir also writes the page images)
import { spawn } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import Papa from 'papaparse';
import { PDFDocument } from 'pdf-lib';

const OUT = join(process.cwd(), 'public', 'demo', 'unfamiliar');
const CHROME = process.env.CHROME;
if (!CHROME || !existsSync(CHROME)) { console.error('Set CHROME to a Chrome or Chromium executable.'); process.exit(1); }
const csv = name => Papa.parse(readFileSync(join(OUT, name), 'utf8'), { skipEmptyLines: false }).data;
const esc = v => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;');

function page({ width, height, tilt, preamble, header, rows, footer, number, pages, numeric }) {
    const tr = r => `<tr>${r.map((c, i) => `<td class="${numeric.includes(i) ? 'n' : ''}">${esc(c)}</td>`).join('')}</tr>`;
    return `<!doctype html><html><head><style>
        body{margin:0;background:#f4f1ea;width:${width}px;height:${height}px;overflow:hidden}
        .p{transform:rotate(${tilt}deg);transform-origin:50% 50%;padding:80px 90px;font:33px/1.33 ${process.env.SCAN_FONT ?? 'Arial,Helvetica,sans-serif'};color:#1d1d22;filter:contrast(.96)}
        h1{font-size:42px;margin:0 0 20px}.pre div{margin:3px 0}.pre span{display:inline-block;min-width:390px}
        table{border-collapse:collapse;margin-top:22px}th{text-align:left;font-weight:700;padding:8px 40px 10px 0;white-space:nowrap}th.n,td.n{text-align:right}
        td{padding:4px 40px 4px 0;white-space:nowrap}.foot{margin-top:40px}.foot div{margin:6px 0}.foot span{display:inline-block;min-width:390px}
        .pg{position:absolute;bottom:50px;left:0;right:0;text-align:center;font-size:25px}</style></head><body><div class="p">
        ${preamble.length ? `<h1>${esc(preamble[0][0])}</h1><div class="pre">${preamble.slice(1).map(l => `<div>${l.map(c => `<span>${esc(c)}</span>`).join('')}</div>`).join('')}</div>` : ''}
        <table><tr>${header.map((h, i) => `<th class="${numeric.includes(i) ? 'n' : ''}">${esc(h)}</th>`).join('')}</tr>${rows.map(tr).join('')}</table>
        ${footer.length ? `<div class="foot">${footer.map(l => `<div>${l.map(c => `<span>${esc(c)}</span>`).join('')}</div>`).join('')}</div>` : ''}
        </div>${pages > 1 ? `<div class="pg">Page ${number} of ${pages}</div>` : ''}</body></html>`;
}

const profile = mkdtempSync(join(tmpdir(), 'fg-scan-'));
const chrome = spawn(CHROME, ['--headless=new', '--remote-debugging-port=0', `--user-data-dir=${profile}`, '--no-first-run', '--hide-scrollbars', '--font-render-hinting=none', 'about:blank'], { stdio: 'ignore' });
const portFile = join(profile, 'DevToolsActivePort');
for (let i = 0; i < 100 && !existsSync(portFile); i++) await new Promise(r => setTimeout(r, 100));
const [port, path] = readFileSync(portFile, 'utf8').trim().split('\n');
const ws = new WebSocket(`ws://127.0.0.1:${port}${path}`);
await new Promise(r => ws.addEventListener('open', r));
let id = 0; const pending = new Map();
ws.addEventListener('message', e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); if (m.error) p.rej(Error(JSON.stringify(m.error))); else p.res(m.result); } });
const send = (method, params = {}, sessionId) => new Promise((res, rej) => { const i = ++id; pending.set(i, { res, rej }); ws.send(JSON.stringify({ id: i, method, params, sessionId })); });
const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
const s = (m, p) => send(m, p, sessionId);
async function shot(html, width, height) {
    await s('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false });
    const file = join(profile, `p${++id}.html`); writeFileSync(file, html);
    await s('Page.navigate', { url: `file://${file}` }); await new Promise(r => setTimeout(r, 400));
    return Buffer.from((await s('Page.captureScreenshot', { format: 'jpeg', quality: 92 })).data, 'base64');
}

// Bank statement: the same preamble, table and footer as the CSV export, as a two-page image-only PDF.
const bank = csv('bank-statement-march-2026-export.csv'), headerAt = bank.findIndex(r => r[0] === 'Date');
const bankRows = bank.slice(headerAt + 1).filter(r => /^\d{2}\/\d{2}\/\d{4}$/.test(r[0])), bankFooter = bank.slice(headerAt + 1 + bankRows.length).filter(r => r.some(Boolean));
const bankPre = bank.slice(0, headerAt).filter(r => r.some(Boolean));
const W = 3508, H = 2480; // A4 landscape at 300 dpi
const pdf = await PDFDocument.create({ updateMetadata: false });
const halves = [bankRows.slice(0, 30), bankRows.slice(30)];
for (const [i, rows] of halves.entries()) {
    const png = await shot(page({ width: W, height: H, tilt: i ? -0.25 : 0.3, preamble: i ? [] : bankPre, header: bank[headerAt], rows, footer: i ? bankFooter : [], number: i + 1, pages: 2, numeric: [5, 6, 7] }), W, H);
    if (process.env.SCAN_PAGES_DIR) writeFileSync(join(process.env.SCAN_PAGES_DIR, `bank-scan-page-${i + 1}.jpg`), png);
    const img = await pdf.embedJpg(png), pg = pdf.addPage([842, 595]);
    pg.drawImage(img, { x: 0, y: 0, width: 842, height: 595 });
}
const fixed = new Date('2026-04-01T00:00:00Z'); pdf.setCreationDate(fixed); pdf.setModificationDate(fixed); pdf.setProducer('FinGence demo generator'); pdf.setCreator('FinGence demo generator');
writeFileSync(join(OUT, 'bank-statement-march-2026-scan.pdf'), Buffer.from(await pdf.save({ useObjectStreams: false })));

// Ledger: one portrait page scanned as JPEG, with a stated totals line.
const ledger = csv('general-ledger-cash-march-2026.csv'), lh = ledger.findIndex(r => r[0] === 'Journal Date');
const ledgerRows = ledger.slice(lh + 1).filter(r => r.length > 2 && r[0]);
const total = col => ledgerRows.reduce((n, r) => n + Math.round(Number((r[col] || '0').replace(/,/g, '')) * 100), 0);
const fmt = c => `${Math.floor(c / 100).toLocaleString('en-US')}.${String(c % 100).padStart(2, '0')}`;
const LW = 2480, LH = 3508; // A4 portrait at 300 dpi
const png = await shot(page({ width: LW, height: LH, tilt: 0.35, preamble: ledger.slice(0, lh).filter(r => r.some(Boolean)), header: ledger[lh], rows: ledgerRows, footer: [['Total debits', fmt(total(5))], ['Total credits', fmt(total(6))]], number: 1, pages: 1, numeric: [5, 6] }).replace('font:33px/1.33', 'font:30px/1.35'), LW, LH);
writeFileSync(join(OUT, 'general-ledger-cash-march-2026-scan.jpg'), png);
ws.close(); chrome.kill();
console.log('Wrote bank-statement-march-2026-scan.pdf and general-ledger-cash-march-2026-scan.jpg');
